/**
 * @file algorithm_template_test.cpp
 * @brief Hand cases of algorithm_template: paper examples, regression seeds, edge cases (PLAN
 *        Section 4.8, file 12; generated by scripts/new_algorithm.py --container hypergraph).
 */
#include <dyng/algorithm_template.hpp>
#include <dyng/core/copy.hpp>
#include <dyng/core/resources.hpp>
#include <dyng/hypergraph/hyperedge_batch.hpp>
#include <dyng/hypergraph/hyperedge_list.hpp>
#include <dyng/hypergraph/hypergraph.hpp>
#include <dyng/update.hpp>

#include <gtest/gtest.h>

#include <cstdint>
#include <vector>

namespace {

using hypergraph_t = dyng::hypergraph<std::int32_t, dyng::unweighted>;

hypergraph_t make_hypergraph(const dyng::resources& res, std::int32_t n,
                             const std::vector<std::vector<std::int32_t>>& hyperedges) {
  dyng::hyperedge_list<std::int32_t, dyng::unweighted> list;
  list.num_vertices = n;
  for (const auto& members : hyperedges) {
    list.add_hyperedge(dyng::host_view(members));
  }
  return hypergraph_t::from_hyperedges(res, list.view());
}

// TODO(algorithm_template): the paper's example and the edge cases of the algorithm.
TEST(AlgorithmTemplate, AnUpdateEqualsCompute) {
  const dyng::resources res = dyng::resources::sequential();
  hypergraph_t h = make_hypergraph(res, 5, {{0, 1}, {1, 2}, {3}});
  auto r = dyng::algorithm_template::compute(res, h);
  dyng::hyperedge_batch<std::int32_t, dyng::unweighted> batch;
  batch.delete_hyperedge(1);
  batch.insert_hyperedge({2, 3});
  const auto s = dyng::algorithm_template::update(res, h, batch.view(), r);
  EXPECT_TRUE(s.fallback_used);                // the placeholder recomputes ("start green")
  EXPECT_EQ(s.batch.inserted_ids.size(), 1U);  // the ids the store chose: read them, never guess
  const auto fresh = dyng::algorithm_template::compute(res, h);
  //@@ fixed_point
  EXPECT_EQ(dyng::to_vector(res, r.labels()), dyng::to_vector(res, fresh.labels()));
  EXPECT_EQ(dyng::to_vector(res, r.labels()), (std::vector<std::int32_t>{0, 0, 2, 2, 4}));
  //@@ end
  //@@ aggregate_delta
  EXPECT_EQ(r.count(), fresh.count());
  EXPECT_EQ(r.count(), 5U);  // |{0, 1}| + |{3}| + |{2, 3}|
                             //@@ end
  EXPECT_EQ(r.graph_version(), h.version());
  // dyng::update() takes the result too (one commit for every result of the hypergraph).
  dyng::hyperedge_batch<std::int32_t, dyng::unweighted> more;
  more.insert_hyperedge({4, 0});
  (void)dyng::update(res, h, more.view(), r);
  EXPECT_EQ(r.graph_version(), h.version());
}

}  // namespace
